import { useCallback, useEffect, useRef, useState } from 'react';
import { RealtimeChannel } from '@supabase/supabase-js';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { supabase } from '../lib/supabase';
import { useAuth } from '../state/auth';
import { useDiamonds } from '../state/diamonds';
import { useStats } from '../state/stats';
import { logEvent } from '../lib/analytics';
import { fx } from '../lib/fx';
import { CellOwner, DuelGrid, checkWin, generateGrid, matchesCriteria } from './gridDuel';

export type DuelRole = 'creator' | 'opponent';

export interface DuelCell {
  owner: CellOwner;
  name: string | null;
}

export interface DuelRow {
  id: string;
  code: string;
  creator_id: string;
  opponent_id: string | null;
  grid: DuelGrid;
  cells: DuelCell[];
  used_players: string[];
  turn: DuelRole;
  status: 'waiting' | 'active' | 'finished' | 'invited' | 'declined';
  winner: DuelRole | 'draw' | null;
  turn_started_at: string;
  creator_name: string | null;
  opponent_name: string | null;
}

export const DUEL_TURN_SECONDS = 40;

// Win/draw payout for a finished duel — nothing for a loss, keeping it
// competitive. Capped per day like every other rewarded mode so ping-ponging
// duels back and forth can't become an unlimited diamond faucet.
const WIN_REWARD = 6;
const DRAW_REWARD = 3;
const WIN_XP = 40;
const DRAW_XP = 15;
const REWARDED_PER_DAY = 5;
const STORAGE_KEY = 'strikr_duel_rewards_v1';

function todayStr(): string {
  return new Date().toISOString().slice(0, 10);
}

const EMPTY_CELLS: DuelCell[] = Array.from({ length: 9 }, () => ({ owner: null, name: null }));

function generateCode(): string {
  return Math.random().toString(36).slice(2, 8).toUpperCase();
}

export function useDuel() {
  const { user } = useAuth();
  const { addDiamonds } = useDiamonds();
  const { recordWin } = useStats();
  const [duel, setDuel] = useState<DuelRow | null>(null);
  const [loading, setLoading] = useState(true);
  const channelRef = useRef<RealtimeChannel | null>(null);
  const rewardedDuelRef = useRef<string | null>(null);
  const [rewardedToday, setRewardedToday] = useState(0);
  const [lastReward, setLastReward] = useState(0);

  useEffect(() => {
    AsyncStorage.getItem(STORAGE_KEY).then((raw) => {
      if (!raw) return;
      try {
        const parsed = JSON.parse(raw);
        if (parsed.date === todayStr()) setRewardedToday(parsed.count || 0);
      } catch {
        // ignore corrupt storage
      }
    });
  }, []);

  const loadActive = useCallback(async () => {
    if (!user) {
      setDuel(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    const { data } = await supabase
      .from('grid_duels')
      .select('*')
      .or(`creator_id.eq.${user.id},opponent_id.eq.${user.id}`)
      .in('status', ['waiting', 'active', 'invited', 'declined'])
      .order('created_at', { ascending: false })
      .limit(1)
      .maybeSingle();
    setDuel((data as DuelRow | null) || null);
    setLoading(false);
  }, [user]);

  useEffect(() => {
    loadActive();
  }, [loadActive]);

  // Separate from the per-duel channel below (which only exists once a duel
  // is already loaded) — this one is keyed by user id so an incoming invite
  // shows up immediately if the invitee is already sitting on the Duel tab.
  useEffect(() => {
    if (!user) return;
    const channel = supabase
      .channel(`duel-invites-${user.id}`)
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'grid_duels', filter: `opponent_id=eq.${user.id}` },
        () => loadActive()
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [user, loadActive]);

  useEffect(() => {
    if (channelRef.current) {
      supabase.removeChannel(channelRef.current);
      channelRef.current = null;
    }
    if (!duel) return;
    const channel = supabase
      .channel(`duel-${duel.id}`)
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'grid_duels', filter: `id=eq.${duel.id}` },
        (payload) => setDuel(payload.new as DuelRow)
      )
      .subscribe();
    channelRef.current = channel;
    return () => {
      supabase.removeChannel(channel);
      channelRef.current = null;
    };
  }, [duel?.id]);

  // Fires once per finished duel (guarded by rewardedDuelRef) regardless of
  // which client actually made the winning move — both participants land
  // here via their own realtime update and credit themselves independently.
  useEffect(() => {
    if (!duel || !user || duel.status !== 'finished') return;
    if (rewardedDuelRef.current === duel.id) return;
    rewardedDuelRef.current = duel.id;
    const role = duel.creator_id === user.id ? 'creator' : 'opponent';
    const won = duel.winner === role;
    const draw = duel.winner === 'draw';
    if (!won && !draw) return;
    const reward = won ? WIN_REWARD : DRAW_REWARD;
    if (rewardedToday < REWARDED_PER_DAY) {
      addDiamonds(reward);
      setLastReward(reward);
      setRewardedToday((prev) => {
        const next = prev + 1;
        AsyncStorage.setItem(STORAGE_KEY, JSON.stringify({ date: todayStr(), count: next })).catch(() => {});
        return next;
      });
    } else {
      setLastReward(0);
    }
    recordWin({ kind: 'duel', firstTry: won, xp: won ? WIN_XP : DRAW_XP });
    fx.win();
  }, [duel, user, rewardedToday, addDiamonds, recordWin]);

  const myRole = useCallback(
    (d: DuelRow): DuelRole => (d.creator_id === user?.id ? 'creator' : 'opponent'),
    [user]
  );

  const createDuel = useCallback(async (): Promise<{ error: string | null }> => {
    if (!user) return { error: 'not_authenticated' };
    const grid = generateGrid();
    const code = generateCode();
    const { data, error } = await supabase
      .from('grid_duels')
      .insert({ code, creator_id: user.id, grid, cells: EMPTY_CELLS, used_players: [], turn: 'creator', status: 'waiting' })
      .select()
      .single();
    if (error) return { error: error.message };
    setDuel(data as DuelRow);
    logEvent(user.id, 'duel_created');
    return { error: null };
  }, [user]);

  const inviteDuel = useCallback(
    async (targetUserId: string, targetName: string): Promise<{ error: string | null }> => {
      if (!user) return { error: 'not_authenticated' };
      const grid = generateGrid();
      const { data, error } = await supabase.rpc('invite_duel', { target_user_id: targetUserId, target_name: targetName, grid });
      if (error) return { error: error.message };
      const newId = Array.isArray(data) ? data[0]?.id : null;
      if (newId) await loadActive();
      logEvent(user.id, 'duel_invite_sent');
      return { error: null };
    },
    [user, loadActive]
  );

  const respondInvite = useCallback(
    async (accept: boolean): Promise<{ error: string | null }> => {
      if (!duel || !user) return { error: 'no_duel' };
      const { error } = await supabase.rpc('respond_duel_invite', { duel_id: duel.id, accept });
      if (error) return { error: error.message };
      if (accept) {
        await loadActive();
      } else {
        setDuel(null);
      }
      logEvent(user.id, accept ? 'duel_invite_accepted' : 'duel_invite_declined');
      return { error: null };
    },
    [duel, user, loadActive]
  );

  const joinDuel = useCallback(
    async (code: string): Promise<{ error: string | null }> => {
      if (!user) return { error: 'not_authenticated' };
      const { error } = await supabase.rpc('join_duel_by_code', { code_arg: code.trim() });
      if (error) return { error: error.message };
      await loadActive();
      return { error: null };
    },
    [user, loadActive]
  );

  const playCell = useCallback(
    async (index: number, name: string): Promise<{ error: string | null }> => {
      if (!duel || !user) return { error: 'no_duel' };
      if (duel.status !== 'active') return { error: 'not_active' };
      const role = myRole(duel);
      if (duel.turn !== role) return { error: 'not_your_turn' };
      if (duel.cells[index].owner) return { error: 'cell_taken' };
      const rowC = duel.grid.rows[Math.floor(index / 3)];
      const colC = duel.grid.cols[index % 3];
      const found = matchesCriteria(name, rowC, colC);
      if (!found) return { error: 'invalid_answer' };
      if (duel.used_players.includes(found.n)) return { error: 'player_used' };

      const cells = duel.cells.slice();
      cells[index] = { owner: role, name: found.n };
      const usedPlayers = [...duel.used_players, found.n];
      const won = checkWin(cells.map((c) => c.owner), role);
      const full = cells.every((c) => c.owner);
      const nextTurn = role === 'creator' ? 'opponent' : 'creator';

      const update = {
        cells,
        used_players: usedPlayers,
        turn: won || full ? duel.turn : nextTurn,
        status: won || full ? ('finished' as const) : ('active' as const),
        winner: won ? role : full ? ('draw' as const) : null,
        turn_started_at: new Date().toISOString(),
      };
      const { error } = await supabase.from('grid_duels').update(update).eq('id', duel.id);
      if (error) return { error: error.message };
      setDuel({ ...duel, ...update });
      if (won || full) logEvent(user.id, 'duel_finished', { result: won ? role : 'draw' });
      return { error: null };
    },
    [duel, user, myRole]
  );

  // Called by whichever client is on the clock when its local 40s countdown
  // hits zero — passes the turn without filling a cell. Guarded by `turn`
  // still matching the caller's role so a stale timer firing after the
  // opponent already moved (or after this player moved) can't double-pass.
  const passTurn = useCallback(async (): Promise<void> => {
    if (!duel || duel.status !== 'active') return;
    const role = myRole(duel);
    if (duel.turn !== role) return;
    const nextTurn: DuelRole = role === 'creator' ? 'opponent' : 'creator';
    const update = { turn: nextTurn, turn_started_at: new Date().toISOString() };
    const { error } = await supabase.from('grid_duels').update(update).eq('id', duel.id).eq('turn', role);
    if (!error) setDuel({ ...duel, ...update });
  }, [duel, myRole]);

  // Either participant can bail out — the other is credited a win rather
  // than leaving the duel stuck forever with no timeout mechanism.
  const forfeit = useCallback(async (): Promise<void> => {
    if (!duel || !user) return;
    const role = myRole(duel);
    const otherRole: DuelRole = role === 'creator' ? 'opponent' : 'creator';
    await supabase.from('grid_duels').update({ status: 'finished', winner: otherRole }).eq('id', duel.id);
    setDuel(null);
  }, [duel, user, myRole]);

  const clearFinished = useCallback(() => setDuel(null), []);

  // Distinct from forfeit(): an unanswered invite has no game to forfeit,
  // so marking it "declined" (rather than a forfeit loss with a winner
  // that never played) is the accurate outcome for the invitee to see.
  const cancelInvite = useCallback(async (): Promise<void> => {
    if (!duel) return;
    await supabase.from('grid_duels').update({ status: 'declined', updated_at: new Date().toISOString() }).eq('id', duel.id);
    setDuel(null);
  }, [duel]);

  return {
    duel,
    loading,
    myRole: duel ? myRole(duel) : null,
    createDuel,
    inviteDuel,
    respondInvite,
    cancelInvite,
    joinDuel,
    playCell,
    passTurn,
    forfeit,
    clearFinished,
    refresh: loadActive,
    lastReward,
    rewardedToday,
    rewardedLimit: REWARDED_PER_DAY,
  };
}
